{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 청년정책조정위원회에서 중도 사임한 위원을 대신해 위촉받은 비공무원의 임기가 새로 2년인지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "중도 사임한 위원을 대신해 위촉받은 위원의 임기는 새로 2년이 시작되지 않습니다. 서울특별시 청년 기본 조례 제9조 제7항은 보궐위원의 임기를 전임자의 남은 기간으로 한다고 정하고 있습니다. 따라서 전임자가 사임한 뒤 남은 기간만큼만 임기를 수행하게 됩니다.",
          "b_ids": "청년:제9조제7항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
